    `  <title>${id}</title>`,
    '  <defs>',
    `    <linearGradient id="b-${id}" x1="0" y1="0" x2="0" y2="1">`,
    `      <stop offset="0" stop-color="${color}"/>`,
    `      <stop offset="1" stop-color="${shade(color, -0.22)}"/>`,
